-- Restores the exact live templates/spawns captured before the demon-mob release.

START TRANSACTION;

DELETE FROM `mob_template` WHERE `id` BETWEEN 120 AND 127;

UPDATE `mob_template`
SET `TYPE` = 1,
    `NAME` = 'Snowman',
    `hp` = 55,
    `range_move` = 33,
    `speed` = 2,
    `dart_Type` = 30,
    `percent_dame` = 5,
    `percent_tiem_nang` = 10
